const cues=[['08:42','I thought you said you had it all figured out.'],['08:46','We did. Then the ground started moving.'],['08:51','Nobody has everything figured out, Claire.'],['08:57','That is exactly what someone without a plan would say.'],['09:03','I have a plan. It involves staying right here.'],['09:09','You know, sometimes you just have to roll with it.'],['09:15','I am not rolling anywhere until this stops.'],['09:21','That seems like a perfectly reasonable strategy.'],['09:27','Can we talk about this after the earthquake?'],['09:32','Sure. I will pencil it in.'],['09:38','You are making a joke right now?'],['09:44','It helps me stay calm.'],['09:50','Well, it is not helping me.']];
const dict={thought:['/θɔt/','以为；认为'],figured:['/ˈfɪɡjərd/','想明白；弄清楚'],out:['/aʊt/','（与 figure 连用）解决'],ground:['/ɡraʊnd/','地面'],moving:['/ˈmuːvɪŋ/','移动'],everything:['/ˈevriθɪŋ/','一切'],plan:['/plæn/','计划'],roll:['/roʊl/','滚动；顺其自然'],reasonable:['/ˈriːzənəbl/','合理的'],strategy:['/ˈstrætədʒi/','策略'],pencil:['/ˈpensl/','把…记入日程']};let saved=['figure out','ground','reasonable','strategy'],selected=0;
const $=s=>document.querySelector(s),toast=m=>{const t=$('#toast');t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1700)};
const layoutKey='scenelingo-v03-layout';
function defaults(){const w=$('.workspace')?.clientWidth||1000;return{left:Math.round(w*.23),right:Math.round(w*.28)}}
function applyLayout(values){const grid=$('.workspace');if(!grid)return;const d=defaults();grid.style.gridTemplateColumns=`minmax(180px,${values.left||d.left}px) 6px minmax(340px,1fr) 6px minmax(245px,${values.right||d.right}px)`;}
function getLayout(){try{return JSON.parse(localStorage.getItem(layoutKey))||defaults()}catch{return defaults()}}
let splittersReady=false;
function setupSplitters(){applyLayout(getLayout());if(!$('#reset-layout')){const b=document.createElement('button');b.id='reset-layout';b.className='square';b.title='恢复默认布局';b.setAttribute('aria-label','恢复默认布局');b.textContent='↔';$('.materials .pane-title').append(b);b.addEventListener('click',()=>{localStorage.removeItem(layoutKey);applyLayout(defaults());toast('已恢复默认布局')})}if(splittersReady)return;splittersReady=true;let drag=null;document.querySelectorAll('.splitter').forEach(el=>el.addEventListener('pointerdown',e=>{if(innerWidth<850)return;const ws=$('.workspace');drag={side:el.dataset.split,start:e.clientX,layout:{left:$('.materials').getBoundingClientRect().width,right:$('.tutor').getBoundingClientRect().width},width:ws.clientWidth};el.classList.add('dragging');try{el.setPointerCapture(e.pointerId)}catch{}e.preventDefault()}));document.addEventListener('pointermove',e=>{if(!drag)return;const delta=e.clientX-drag.start,next={...drag.layout};if(drag.side==='left')next.left=Math.max(190,Math.min(drag.width*.36,drag.layout.left+delta));else next.right=Math.max(245,Math.min(drag.width*.4,drag.layout.right-delta));applyLayout(next);drag.current=next});document.addEventListener('pointerup',()=>{if(!drag)return;localStorage.setItem(layoutKey,JSON.stringify(drag.current||drag.layout));document.querySelectorAll('.splitter').forEach(x=>x.classList.remove('dragging'));drag=null})}
function render(){const box=$('#captions');box.innerHTML='';cues.forEach(([time,line],i)=>{const row=document.createElement('div');row.className='cue'+(i===selected?' selected':'');row.dataset.i=i;const words=line.match(/[A-Za-z']+|[^A-Za-z']+/g)||[];row.innerHTML=`<time>${time}</time><p>${words.map(w=>/^[A-Za-z']+$/.test(w)?`<button class="word ${saved.includes(w.toLowerCase())?'saved':''}" data-word="${w.toLowerCase()}">${w}</button>`:w).join('')}</p>`;box.append(row)});$('#context').textContent='“'+cues[selected][1]+'”';$('#wordlist').innerHTML=['figure out','ground','reasonable','strategy','moving'].map(w=>`<div class="wordrow"><span>${w}</span><small>${saved.includes(w)?'已收藏':'待学习'}</small><button data-save="${w}">${saved.includes(w)?'✓':'＋'}</button></div>`).join('');$('#count').textContent=saved.length;$('#vocabgrid').innerHTML=saved.map(w=>`<article class="vocabcard"><b>${w}</b><p>${dict[w.split(' ')[0]]?.[0]||'/ˈwɜːrd/'}</p><span>演示释义 · 来自 Modern Family</span></article>`).join('')}
document.addEventListener('click',e=>{const page=e.target.closest('[data-page]');if(page){document.querySelectorAll('.nav nav button').forEach(b=>b.classList.toggle('active',b===page));document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!==page.dataset.page);if(page.dataset.page==='home'){$('#title').innerHTML='<span id="greeting-period"></span>，<span id="daily-encouragement"></span>';window.SceneLingoDailyGreeting.refresh()}else $('#title').textContent=page.dataset.page==='workbench'?'沉浸在场景里学习。':page.dataset.page==='vocab'?'把遇见的词，变成自己的。':'按自己的节奏，完成今天的复习。';if(page.dataset.page==='workbench')setupSplitters();return}if(e.target.closest('[data-open]')){document.querySelector('[data-page="workbench"]').click();return}if(e.target.closest('.material')){document.querySelectorAll('.material').forEach(m=>m.classList.toggle('selected',m===e.target.closest('.material')));toast('已选择资料（演示）');return}const word=e.target.closest('[data-word]');if(word){const w=word.dataset.word,info=dict[w]||['/ˈwɜːrd/','语境中的常用表达'];const p=$('#popover');p.innerHTML=`<button class="pop-close" aria-label="关闭词卡" title="关闭">×</button><h3>${word.textContent}</h3><div class="ipa">${info[0]}</div><p>${info[1]} <small>· 演示释义</small></p><button data-save="${w}">${saved.includes(w)?'已在生词库':'＋ 加入生词库'}</button> <button id="speak">🔊 朗读</button>`;p.hidden=false;const r=word.getBoundingClientRect();p.style.left=Math.max(12,Math.min(r.left,innerWidth-290))+'px';p.style.top=Math.max(12,Math.min(r.bottom+8,innerHeight-190))+'px';return}if(e.target.closest('.pop-close')){$('#popover').hidden=true;return}if(e.target.closest('[data-save]')){const w=e.target.closest('[data-save]').dataset.save;if(!saved.includes(w))saved.push(w);render();$('#popover').hidden=true;toast(`“${w}”已加入生词库（演示）`);return}if(e.target.id==='speak'){speechSynthesis?.speak(new SpeechSynthesisUtterance($('.popover h3').textContent));toast('正在使用浏览器语音演示');return}const cue=e.target.closest('.cue');if(cue){selected=+cue.dataset.i;render();return}if(e.target.id==='next'||e.target.id==='prev'){selected=(selected+(e.target.id==='next'?1:-1)+cues.length)%cues.length;render();$('#captions .selected').scrollIntoView({block:'nearest',behavior:'smooth'});return}if(e.target.id==='send'){send()}if(e.target.closest('.quick button')){$('#input').value=e.target.closest('button').textContent;send()}if(e.target.id==='newchat'||e.target.id==='clear'){ $('#messages').innerHTML='';toast('已新建本地演示会话')}if(e.target.id==='history')toast('历史会话：Scene vocabulary · Earthquake（演示）');if(e.target.id==='import'||e.target.id==='import2'){const input=document.createElement('input');input.type='file';input.accept='.srt,.vtt';input.onchange=()=>toast(input.files[0]?.name+' · 演示导入');input.click()}if(e.target.id==='play'){e.target.textContent=e.target.textContent==='▶'?'Ⅱ':'▶';toast('演示播放控制')}if(e.target.id==='startreview'){ $('#reviewresult').innerHTML='<p><b>figure out</b> · 想一想这个短语的意思。</p><button class="primary" id="answer">显示答案</button>';return}if(e.target.id==='answer'){e.target.outerHTML='<p>figure out = 弄清楚、想明白 <button id="answer">记住了 ✓</button></p>';toast('复习完成（演示）')}if(e.target.id==='settings')toast('设置面板属于演示范围外');if(e.target.id==='help'||e.target.id==='more'||e.target.closest('.video-controls button:not(#play)'))toast('SceneLingo V0.3 演示原型');});
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#popover').hidden=true});
function send(){const input=$('#input'),v=input.value.trim();if(!v)return;const m=$('#messages'),u=document.createElement('div'),a=document.createElement('div');u.className='bubble user';u.innerHTML='<p></p><small>现在</small>';u.querySelector('p').textContent=v;a.className='bubble ai';a.innerHTML='<label>✦ &nbsp;AI TUTOR · 演示回复</label><p></p><small>现在</small>';a.querySelector('p').textContent=`Great question! “${v.split(' ').slice(-2).join(' ')}” is used naturally in this scene. Notice how context helps express the meaning.`;m.append(u,a);input.value='';m.scrollTop=m.scrollHeight}
$('#input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}});window.addEventListener('resize',()=>{if(!$('.workspace')?.offsetParent)return;applyLayout(getLayout())});render();window.SceneLingoDailyGreeting.start();
